const API=async()=>{const r=await fetch(new URL('./api-config.json',document.baseURI),{cache:'no-store'});const c=await r.json();if(!c.apiBase)throw Error('RSVP service is not configured yet.');return c.apiBase.replace(/\/$/,'')};
const dialog=document.createElement('dialog');dialog.id='kam-rsvp-dialog';dialog.style.cssText='border:1px solid #c6ae83;border-radius:24px;padding:24px;width:min(88vw,400px);max-height:85dvh;background:#fff9ef;color:#482c30;box-shadow:0 20px 80px #0006;z-index:2147483002';dialog.innerHTML='<form id="public-rsvp" style="display:grid;gap:14px"><button type="button" data-close style="justify-self:end">Close</button><h2 style="margin:0;font-family:Georgia">RSVP</h2><p>Strictly on invitation<br>This invitation allows two persons<br>Colour of the day: All White</p><label>Full name<input name="name" required maxlength="100" autocomplete="name"></label><label>Phone number<input name="phone" required type="tel" autocomplete="tel" maxlength="25"></label><label>Will you attend?<select name="attendance"><option value="yes">Joyfully accept</option><option value="no">Regretfully decline</option></select></label><label id="guest-field">Number of persons (including you)<select name="guests"><option value="1">1</option><option value="2">2</option></select></label><button type="submit">Send RSVP</button><p role="status" aria-live="polite" style="margin:0"></p></form>';document.body.append(dialog);const style=document.createElement('style');style.textContent='dialog::backdrop{background:#200c18aa;backdrop-filter:blur(8px)}#public-rsvp label{display:grid;gap:6px}#public-rsvp input,#public-rsvp select,#public-rsvp button{font:inherit;padding:12px;border:1px solid #cdb99a;border-radius:12px;background:#fff;color:#482c30}#public-rsvp button[type=submit]{background:#b18a50;color:white}';document.head.append(style);const f=dialog.querySelector('form'),status=f.querySelector('[role=status]');f.elements.attendance.onchange=()=>{dialog.querySelector('#guest-field').hidden=f.elements.attendance.value==='no'};dialog.querySelector('[data-close]').onclick=()=>dialog.close();document.addEventListener('click',e=>{if(e.target.closest('[data-invite="rsvp"],#rsvp-button')){e.preventDefault();e.stopImmediatePropagation();if(!dialog.open){document.body.classList.add('rsvp-modal-open');dialog.showModal();requestAnimationFrame(()=>{if(!receipt)f.elements.name.focus({preventScroll:true})})}}},true);
dialog.addEventListener('close',()=>document.body.classList.remove('rsvp-modal-open'));for(const type of ['pointerdown','pointerup','mousedown','mouseup','touchstart','touchend','click','keydown','keyup','wheel'])dialog.addEventListener(type,e=>e.stopPropagation());
const KEY='babykamkam-confirmation-v1';let receipt=null;try{receipt=JSON.parse(localStorage.getItem(KEY))}catch{}
const panel=document.createElement('section');panel.hidden=true;panel.className='receipt-panel';dialog.append(panel);
const css=document.createElement('style');css.textContent=`.receipt-panel[hidden],#public-rsvp[hidden]{display:none!important}.receipt-panel{text-align:center;color:#592839}.receipt-ticket{font-family:Georgia,serif;padding:24px 14px;background:linear-gradient(145deg,#fffdf7,#f4e6cf);border:1px solid #b99760;outline:1px solid #dfc9a3;outline-offset:-7px}.receipt-ticket small{font:10px system-ui;letter-spacing:.18em;text-transform:uppercase;color:#94713c}.receipt-ticket h2{font-weight:400;font-size:27px}.receipt-ticket dl{display:grid;gap:12px}.receipt-ticket dt{font:10px system-ui;letter-spacing:.1em;text-transform:uppercase;color:#94713c}.receipt-ticket dd{margin:4px 0 0}.receipt-ticket img{width:90px;height:auto}.receipt-actions{display:grid;gap:8px;margin-top:15px}.receipt-actions button{font:inherit;padding:12px;border:1px solid #c6a36b;border-radius:12px;color:white;background:#592839;cursor:pointer}@media print{body>*:not(dialog.receipt-print){display:none!important}dialog.receipt-print{position:static!important;display:block!important;width:100%!important;max-height:none!important;overflow:visible!important;margin:0!important;box-shadow:none!important;border:0!important}dialog.receipt-print::backdrop,.receipt-actions,#public-rsvp{display:none!important}.receipt-ticket{print-color-adjust:exact;-webkit-print-color-adjust:exact}}`;document.head.append(css);
function updateReceipt(){for(const b of document.querySelectorAll('[data-invite="rsvp"]')){if(!receipt)continue;if(b.querySelector('strong'))b.querySelector('strong').textContent='My RSVP';if(b.querySelector('span'))b.querySelector('span').textContent='view confirmation'}dialog.classList.toggle('receipt-mode',!!receipt);f.hidden=!!receipt;panel.hidden=!receipt;if(!receipt)return;const yes=receipt.attendance==='yes';panel.innerHTML='<button type="button" class="receipt-close" data-close-receipt aria-label="Close receipt">×</button><article class="receipt-ticket"><small>Baby Kam Kam · RSVP confirmation</small><h2></h2><p>This certifies the response of</p><strong data-name style="font-size:24px;overflow-wrap:anywhere"></strong><p style="color:#b99760">──── ✦ ────</p><dl></dl><img src="./assets/seal.png" alt="Baby Kam Kam wax seal"><p>Strictly on invitation<br>Colour of the day: All White</p></article><div class="receipt-actions"><button data-download>Download receipt</button><button data-share>Share on WhatsApp</button></div>';const title=yes?'Your Place Is Reserved':'Your Response Is Received';const fields=[['Event','Baby Kam Kam'],['Date','Sunday, 13 December 2026 · 2 PM'],['Venue','K’ville, No. 16 Ituku Street, Upper Chime, New Haven'],['Response',yes?'Joyfully accepts':'Regretfully declines'],...(yes?[['Party size',String(receipt.guests)+(Number(receipt.guests)===1?' person':' persons')]]:[]),['Confirmed',new Date(receipt.submittedAt).toLocaleDateString()]];if(receipt.code)fields.push(['Reference',String(receipt.code)]);panel.querySelector('h2').textContent=title;panel.querySelector('[data-name]').textContent=receipt.name;for(const [k,v] of fields){const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;div.append(dt,dd);panel.querySelector('dl').append(div)}panel.querySelector('[data-close-receipt]').onclick=()=>dialog.close();panel.querySelector('[data-share]').onclick=()=>window.open('https://wa.me/?text='+encodeURIComponent([title,receipt.name,...fields.map(([k,v])=>k+': '+v)].join('\n')),'_blank','noopener,noreferrer');panel.querySelector('[data-download]').onclick=async()=>{const c=document.createElement('canvas');c.width=1080;c.height=1900;const x=c.getContext('2d');x.textAlign='center';const wrap=(value,size,max=780)=>{x.font=size+'px Georgia';const lines=[];let current='';for(const word of String(value).split(/\s+/)){if(current&&x.measureText(current+' '+word).width>max){lines.push(current);current=word}else current+=(current?' ':'')+word}if(current)lines.push(current);return lines};const blocks=[{v:'BABY KAM KAM  ·  RSVP CONFIRMATION',size:25,gap:48},{v:title,size:54,gap:38},{v:'This certifies the response of',size:29,gap:20},{v:receipt.name,size:50,gap:58},...fields.flatMap(([k,v])=>[{v:k.toUpperCase(),size:22,gap:12,gold:true},{v,size:34,gap:35}])];let total=0;for(const block of blocks){block.lines=wrap(block.v,block.size);total+=block.lines.length*block.size*1.27+block.gap}c.height=Math.ceil(120+total+310);x.fillStyle='#fff8e9';x.fillRect(0,0,c.width,c.height);x.strokeStyle='#b99760';x.lineWidth=4;x.strokeRect(38,38,c.width-76,c.height-76);x.lineWidth=1;x.strokeRect(54,54,c.width-108,c.height-108);x.textAlign='center';x.textBaseline='top';let y=120;for(const block of blocks){x.fillStyle=block.gold?'#94713c':'#592839';x.font=block.size+'px Georgia';for(const line of block.lines){x.fillText(line,540,y,780);y+=block.size*1.27}y+=block.gap}try{const im=new Image();im.src='./assets/seal.png';await im.decode();const scale=Math.min(168/im.width,168/im.height);x.drawImage(im,540-im.width*scale/2,y+8,im.width*scale,im.height*scale)}catch{}x.fillStyle='#592839';x.font='26px Georgia';x.fillText('Strictly on invitation',540,y+210);x.fillText('Colour of the day: All White',540,y+248);c.toBlob(blob=>{if(!blob)return;const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='baby-kamkam-rsvp.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)},'image/png')}}
updateReceipt();

 f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;status.textContent='Saving…';try{const base=await API();const r=await fetch(base+'/api/rsvp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.elements.name.value,phone:f.elements.phone.value,attendance:f.elements.attendance.value,guests:f.elements.attendance.value==='yes'?Number(f.elements.guests.value):0})});const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to save');receipt={name:f.elements.name.value.trim(),attendance:f.elements.attendance.value,guests:f.elements.attendance.value==='yes'?Number(f.elements.guests.value):0,submittedAt:new Date().toISOString(),code:data.receiptCode||data.id||null};try{localStorage.setItem(KEY,JSON.stringify(receipt))}catch{}updateReceipt();status.textContent='';f.reset();f.elements.attendance.onchange()}catch(e){status.textContent=e.message+' Please try again.'}finally{b.disabled=false}};
